corrected_code:
router.post('/orders/duplicate', async (req, res) => {
  const sourceOrder = await Order.findOne({ _id: req.body.sourceId, userId: req.user.id });
  if (!sourceOrder) return res.status(404).send();
  const newOrder = await Order.create({ ...sourceOrder.toObject(), _id: undefined });
  res.json(newOrder);
});
